{"command":"cat > /workspace/src/main.rs <<'RS'
use anyhow::{Context, Result};
use clap::Command;
use crossterm::{
    event::{self, Event, KeyCode, KeyEvent, KeyModifiers},
    execute,
    terminal::{disable_raw_mode, enable_raw_mode, EnterAlternateScreen, LeaveAlternateScreen},
};
use git2::{Oid, Repository, Sort};
use ratatui::{
    Terminal,
    backend::CrosstermBackend,
    layout::{Constraint, Direction, Layout, Rect},
    style::{Color, Modifier, Style},
    text::{Line, Span},
    widgets::{Block, Borders, Paragraph},
    Frame,
};
use std::collections::{HashMap, HashSet};
use std::io::stdout;
use std::path::PathBuf;
use std::time::{Duration, Instant};

// ============ Config ============
#[derive(Debug, Clone)]
struct RefreshConfig {
    auto_refresh: bool,
    refresh_interval: u64,
    auto_fetch: bool,
    fetch_interval: u64,
}
impl Default for RefreshConfig {
    fn default() -> Self {
        Self { auto_refresh: true, refresh_interval: 10, auto_fetch: true, fetch_interval: 60 }
    }
}
fn load_config() -> RefreshConfig {
    let mut cfg = RefreshConfig::default();
    let path = if let Ok(home) = std::env::var("HOME") {
        PathBuf::from(home).join(".config/keifu/config.toml")
    } else if let Some(d) = dirs::config_dir() {
        d.join("keifu/config.toml")
    } else { return cfg; };
    if let Ok(content) = std::fs::read_to_string(&path) {
        if let Ok(val) = content.parse::<toml::Value>() {
            if let Some(refresh) = val.get("refresh") {
                if let Some(b) = refresh.get("auto_refresh").and_then(|v| v.as_bool()) {
                    cfg.auto_refresh = b;
                }
                if let Some(i) = refresh.get("refresh_interval").and_then(|v| v.as_integer()) {
                    let v = i as i64;
                    if v >= 1 { cfg.refresh_interval = v as u64; }
                    else if v < 1 { cfg.refresh_interval = 1; }
                }
                if let Some(b) = refresh.get("auto_fetch").and_then(|v| v.as_bool()) {
                    cfg.auto_fetch = b;
                }
                if let Some(i) = refresh.get("fetch_interval").and_then(|v| v.as_integer()) {
                    let v = i as i64;
                    if v >= 10 { cfg.fetch_interval = v as u64; }
                    else { cfg.fetch_interval = 10; }
                }
            }
        }
    }
    if cfg.refresh_interval < 1 { cfg.refresh_interval = 1; }
    if cfg.fetch_interval < 10 { cfg.fetch_interval = 10; }
    cfg
}

// ============ Git data ============
#[derive(Debug, Clone)]
struct BranchEntry {
    name: String, // for local: "main", for remote: "origin/foo"
    short: String, // display short? for remote "origin/foo"
    is_remote: bool,
    target: Oid,
}

#[derive(Debug, Clone)]
struct CommitData {
    id: Oid,
    short: String,
    full_message: String,
    subject: String,
    author: String,
    email: String,
    date: i64, // timestamp
    date_str: String, // "2026-09-13 17:59:50"
    date_short: String, // "2026-09-13"
    parents: Vec<Oid>,
    parents_short: Vec<String>,
}

#[derive(Debug, Clone)]
struct ChangedFile {
    status: char, // M, A, D
    path: String,
    added: usize,
    deleted: usize,
    is_binary: bool,
}

#[derive(Debug, Clone)]
struct UncommittedInfo {
    count: usize,
    files: Vec<ChangedFile>,
    total_added: usize,
    total_deleted: usize,
}

fn lane_color(idx: usize) -> Color {
    if idx == 0 { return Color::Indexed(12); }
    const PALETTE: [u8; 9] = [2,5,3,1,14,10,13,11,9];
    let c = PALETTE[(idx - 1) % PALETTE.len()];
    Color::Indexed(c)
}

fn branch_label_color_for_lane(lane: usize) -> Color {
    lane_color(lane)
}

// display rows
#[derive(Debug, Clone)]
enum RowKind {
    Uncommitted,
    Commit { commit_idx: usize },
    Connector { lanes_before: Vec<Option<usize>>, lanes_after: Vec<Option<usize>>, max_lanes: usize },
}

#[derive(Debug, Clone)]
struct DisplayRow {
    kind: RowKind,
    // graph segments: Vec<(String, Color, bool bold)>? We'll render directly
}

struct RepoState {
    repo_path: PathBuf,
    repo_name: String,
    head_branch: Option<String>, // Some("main") if on branch, None if detached or unborn
    head_oid: Option<Oid>,
    is_detached: bool,
    branches: Vec<BranchEntry>, // all branches
    local_branches: HashMap<String, Oid>, // name -> oid
    remote_branches: HashMap<String, Oid>, // "origin/foo" -> oid
    commits: Vec<CommitData>, // ordered newest first
    commit_index: HashMap<Oid, usize>,
    // labels per commit idx: Vec<String> sorted HEAD first then alpha
    labels: Vec<Vec<String>>,
    // map label -> is_remote? for delete/checkout logic: need to know if label is remote-only
    // For labels like "foo ↔ origin", the local name is "foo"
    uncommitted: Option<UncommittedInfo>,
    rows: Vec<DisplayRow>,
    max_lanes: usize,
    // per commit lane
    commit_lanes: Vec<usize>,
}

impl RepoState {
    fn load(repo: &Repository) -> Result<Self> {
        // repo name: workdir basename or path basename
        let repo_name = if let Some(wd) = repo.workdir() {
            wd.file_name().map(|s| s.to_string_lossy().to_string()).unwrap_or_else(|| "repo".to_string())
        } else {
            repo.path().parent().and_then(|p| p.file_name()).map(|s| s.to_string_lossy().to_string()).unwrap_or_else(|| "repo".to_string())
        };
        // HEAD
        let mut head_branch: Option<String> = None;
        let mut head_oid: Option<Oid> = None;
        let mut is_detached = false;
        match repo.head() {
            Ok(h) => {
                if h.is_branch() {
                    if let Some(n) = h.shorthand() {
                        head_branch = Some(n.to_string());
                    }
                    if let Ok(oid) = h.peel_to_commit().map(|c| c.id()) {
                        head_oid = Some(oid);
                    } else if let Some(t) = h.target() {
                        head_oid = Some(t);
                    }
                } else {
                    // detached or other
                    is_detached = true;
                    if let Ok(c) = h.peel_to_commit() {
                        head_oid = Some(c.id());
                    } else if let Some(t) = h.target() {
                        head_oid = Some(t);
                    }
                }
            }
            Err(_) => {
                // unborn or no head
                // try to get branch name from unborn? e.g., refs/heads/main but no commits
                // For empty repo, head_branch should be None (status shows no branch)
                head_branch = None;
                head_oid = None;
            }
        }
        // branches
        let mut branches: Vec<BranchEntry> = Vec::new();
        let mut local_map: HashMap<String, Oid> = HashMap::new();
        let mut remote_map: HashMap<String, Oid> = HashMap::new();
        // local
        if let Ok(bi) = repo.branches(Some(git2::BranchType::Local)) {
            for b in bi {
                if let Ok((b, _)) = b {
                    if let Ok(Some(name)) = b.name().map(|n| n.map(|s| s.to_string())) {
                        // Actually b.name returns Result<Option<&str>>
                    }
                    // use shorthand
                    let name_opt = b.name().ok().flatten().map(|s| s.to_string());
                    if let Some(name) = name_opt {
                        if let Ok(target) = b.get().peel_to_commit().map(|c| c.id()) {
                            local_map.insert(name.clone(), target);
                            branches.push(BranchEntry { name: name.clone(), short: name.clone(), is_remote: false, target });
                        } else if let Ok(oid) = b.get().target().ok_or(git2::Error::from_str("no target")).and_then(|o| o.ok_or(git2::Error::from_str("no"))) {
                            // fallback
                            let _ = oid;
                        }
                    }
                }
            }
        }
        // remote origin only
        if let Ok(bi) = repo.branches(Some(git2::BranchType::Remote)) {
            for b in bi {
                if let Ok((b, _)) = b {
                    let name_opt = b.name().ok().flatten().map(|s| s.to_string());
                    if let Some(name) = name_opt {
                        if name == "origin/HEAD" { continue; }
                        if !name.starts_with("origin/") { continue; }
                        // skip symbolic? check if branch is symbolic? git2 Branch doesn't expose directly, but peel will fail for symbolic? origin/HEAD is symbolic, already skipped.
                        if let Ok(c) = b.get().peel_to_commit() {
                            let oid = c.id();
                            remote_map.insert(name.clone(), oid);
                            branches.push(BranchEntry { name: name.clone(), short: name.clone(), is_remote: true, target: oid });
                        }
                    }
                }
            }
        }
        // collect commits via revwalk
        let mut commits: Vec<CommitData> = Vec::new();
        let mut commit_index: HashMap<Oid, usize> = HashMap::new();
        // Gather tips: all local + remote + head_oid
        let mut tips: HashSet<Oid> = HashSet::new();
        for o in local_map.values() { tips.insert(*o); }
        for o in remote_map.values() { tips.insert(*o); }
        if let Some(h) = head_oid { tips.insert(h); }
        if !tips.is_empty() {
            let mut walk = repo.revwalk().unwrap();
            walk.set_sorting(Sort::TIME).ok();
            // Also try topological? Use TIME only to match? But need topo for same-time parent/child.
            // git2 Sort is bitflags: TIME | TOPOLOGICAL
            walk.set_sorting(Sort::TIME | Sort::TOPOLOGICAL).ok();
            for t in &tips {
                walk.push(*t).ok();
            }
            // hide? no
            let mut count = 0;
            for oid_res in walk {
                if count >= 500 { break; }
                if let Ok(oid) = oid_res {
                    if commit_index.contains_key(&oid) { continue; }
                    if let Ok(c) = repo.find_commit(oid) {
                        let msg_full = c.message().unwrap_or("").to_string();
                        // trim trailing newlines? Keep as is but split lines
                        let subject = msg_full.lines().next().unwrap_or("").to_string();
                        let author = c.author();
                        let aname = author.name().unwrap_or("").to_string();
                        let email = author.email().unwrap_or("").to_string();
                        let time = c.time();
                        let ts = time.seconds();
                        // format date using chrono? Use git time + offset? Original shows local time? Our test shows 2026-09-13 17:59:50 for commits with committer date now (UTC?).
                        // Use chrono Local? Or UTC? Let's use chrono with timestamp and format.
                        // For short date, "YYYY-MM-DD"
                        // Need to handle timezone: git time has offset. Use chrono::DateTime with offset?
                        let dt = chrono::DateTime::from_timestamp(ts, 0).map(|d| d.format("%Y-%m-%d %H:%M:%S").to_string()).unwrap_or_default();
                        let ds = chrono::DateTime::from_timestamp(ts, 0).map(|d| d.format("%Y-%m-%d").to_string()).unwrap_or_default();
                        // Actually should use local timezone? But container is UTC, so same.
                        let mut parents = Vec::new();
                        let mut parents_short = Vec::new();
                        for p in c.parents() {
                            parents.push(p.id());
                            parents_short.push(short_id(p.id()));
                        }
                        let short = short_id(oid);
                        let idx = commits.len();
                        commit_index.insert(oid, idx);
                        commits.push(CommitData { id: oid, short, full_message: msg_full.trim_end().to_string(), subject, author: aname, email, date: ts, date_str: dt, date_short: ds, parents, parents_short });
                        count += 1;
                    }
                }
            }
        }
        // labels per commit
        let mut labels: Vec<Vec<String>> = vec![Vec::new(); commits.len()];
        for (idx, cd) in commits.iter().enumerate() {
            let mut labs: Vec<String> = Vec::new();
            // locals at this commit
            for (lname, loid) in &local_map {
                if *loid == cd.id {
                    // check remote same
                    let rname = format!("origin/{}", lname);
                    if let Some(roid) = remote_map.get(&rname) {
                        if *roid == cd.id {
                            labs.push(format!("{} ↔ origin", lname));
                        } else {
                            labs.push(lname.clone());
                        }
                    } else {
                        labs.push(lname.clone());
                    }
                }
            }
            // remotes at this commit where local not same
            for (rname, roid) in &remote_map {
                if *roid == cd.id {
                    // check if local same-named exists and same commit (already aggregated)
                    if let Some(short) = rname.strip_prefix("origin/") {
                        if let Some(loid) = local_map.get(short) {
                            if *loid == cd.id {
                                continue; // aggregated, skip
                            }
                        }
                    }
                    labs.push(rname.clone());
                }
            }
            // sort: HEAD first, then alpha
            // Determine HEAD label: if head_branch Some(b), find lab that corresponds to b (either "b" or "b ↔ origin")
            let head_lab: Option<String> = if let Some(hb) = &head_branch {
                // find lab starting with hb
                labs.iter().find(|l| *l == hb || l.starts_with(&format!("{} ", hb)) || l.starts_with(&format!("{} ↔", hb))).cloned()
            } else { None };
            labs.sort();
            if let Some(hl) = head_lab {
                // move to front
                if let Some(pos) = labs.iter().position(|x| x == &hl) {
                    let v = labs.remove(pos);
                    labs.insert(0, v);
                }
            }
            labels[idx] = labs;
        }
        // uncommitted
        let uncommitted = if head_oid.is_some() {
            detect_uncommitted(repo)?
        } else { None };
        // graph lanes
        let (rows, max_lanes, commit_lanes) = build_graph(&commits, &labels, head_oid, uncommitted.is_some());
        Ok(Self {
            repo_path: repo.workdir().map(|p| p.to_path_buf()).unwrap_or_else(|| repo.path().to_path_buf()),
            repo_name,
            head_branch,
            head_oid,
            is_detached,
            branches,
            local_branches: local_map,
            remote_branches: remote_map,
            commits,
            commit_index,
            labels,
            uncommitted,
            rows,
            max_lanes,
            commit_lanes,
        })
    }
    fn label_for(&self, commit_idx: usize, branch_sel: usize) -> Option<String> {
        self.labels.get(commit_idx).and_then(|v| v.get(branch_sel).cloned())
    }
}

fn short_id(oid: Oid) -> String {
    let s = oid.to_string();
    s[..7.min(s.len())].to_string()
}

fn detect_uncommitted(repo: &Repository) -> Result<Option<UncommittedInfo>> {
