    // Better: diff tree to index + index to workdir, combine.
    // Let's try diff_tree_to_index + diff_index_to_workdir
    let mut all_files: HashMap<String, (char, usize, usize, bool)> = HashMap::new();
    // staged: tree -> index
    if let Some(ht) = head_tree {
        if let Ok(mut idx) = repo.index() {
            if let Ok(diff) = repo.diff_tree_to_index(Some(ht), Some(&idx), None) {
                collect_diff_stats(&diff, &mut all_files, true)?;
            }
            // unstaged: index -> workdir
