        for e in statuses.iter() {
            if let Some(p) = e.path() {
                let st = e.status();
                // determine M/A/D? For staged new (INDEX_NEW) -> A, deleted -> D, else M
                let c = if st.contains(git2::Status::INDEX_NEW) || st.contains(git2::Status::WT_NEW) { 'A' }
                else if st.contains(git2::Status::INDEX_DELETED) || st.contains(git2::Status::WT_DELETED) { 'D' }
                else { 'M' };
                all_files.insert(p.to_string(), (c, 0, 0, false));
            }
        }
        if all_files.is_empty() {
            return Ok(None);
        }
    }
    // Convert to vec sorted? Original order for uncommitted: feat.txt first, a.txt second (not alpha: feat before a? Actually feat.txt staged, a.txt unstaged – staged first? Or sorted by status? Let's sort alphabetically? But earlier feat before a contradicts alpha (a before feat). So order is not alpha. Could be staged first then unstaged? Or diff order (tree->index first, then index->workdir, with staged files first)? Our all_files insertion order: staged first (feat), then unstaged (a) – matches observed (feat first, a second). HashMap loses order, need to preserve insertion order: use Vec? Let's collect in order: staged files in diff order, then unstaged files not already present appended? For overlapping file (both staged+unstaged), combine counts? Need to handle.
        // For now, sort? But to match observed, don't sort, preserve diff order. Let's re-collect with order.
    }
    // Re-collect with order preservation
    let mut ordered: Vec<ChangedFile> = Vec::new();
    let mut seen: HashSet<String> = HashSet::new();
    // To preserve order, we need to iterate diffs in order and merge. Our all_files HashMap lost order. Let's redo with ordered collection.
    // Instead, collect again with order:
    let mut ordered_map: Vec<(String, (char, usize, usize, bool))> = Vec::new();
