                    if let Some(d) = diff2.get_delta(i) {
                        let f = d.new_file().path().or(d.old_file().path()).map(|p| p.to_string_lossy().to_string()).unwrap_or_default();
                        if f.is_empty() { continue; }
                        let status = match d.status() {
                            git2::Delta::Added => 'A',
                            git2::Delta::Deleted => 'D',
                            _ => 'M',
                        };
                        let (a, del, bin) = file_patch_stats(repo, &diff2, i);
                        if let Some(&pos) = map.get(&f) {
                            let e = &mut ordered_map[pos].1;
                            // if existing is A and new is M, keep A? Else keep existing? For simplicity, keep existing status unless existing M and new D? Actually if staged M + unstaged D (deleted), should be D? Hmm. Let's keep D if either D, else A if either A and not D? Simplify: if new is D, set D; else if existing is M and new is A? Keep M? We'll just keep first unless new is D.
                            if status == 'D' { e.0 = 'D'; }
                            e.1 += a; e.2 += del; if bin { e.3 = true; }
                        } else {
                            map.insert(f.clone(), ordered_map.len());
                            ordered_map.push((f, (status, a, del, bin)));
                        }
                    }
                }
            }
        }
    }
    if ordered_map.is_empty() {
        return Ok(None);
    }
    let mut total_a = 0; let mut total_d = 0;
    for (_, ( _, a, d, bin)) in &ordered_map {
        if !*bin { total_a += *a; total_d += *d; }
    }
    // Cap files at 50? Docs say up to 50. But header shows total count (60) with +50? For uncommitted, cap similarly? Likely same 50 cap for display, but count shows total? For uncommitted (1) with 2 files, no cap. For many uncommitted files, need cap. We'll cap display at 50, but total count is all? Header for uncommitted detail: "N files with changes" where N is total? And files panel header "N files changed +A -D" where A/D sum first 50? Let's implement same as commits: total files = all, sums = first 50.
    let total_files = ordered_map.len();
    // For sums, only first 50
    let mut sum_a50 = 0; let mut sum_d50 = 0;
    for (_, (_, a, d, bin)) in ordered_map.iter().take(50) {
        if !*bin { sum_a50 += *a; sum_d50 += *d; }
    }
    // Build ChangedFile vec (up to 50? Or all? Display will truncate to fit height, but store up to 50? Docs say up to 50, so store 50)
    let mut files: Vec<ChangedFile> = Vec::new();
    for (path, (st, a, d, bin)) in ordered_map.into_iter().take(50) {
        files.push(ChangedFile { status: st, path, added: a, deleted: d, is_binary: bin });
    }
    Ok(Some(UncommittedInfo { count: total_files, files, total_added: sum_a50, total_deleted: sum_d50 }))
}

fn collect_diff_stats(_diff: &git2::Diff, _map: &mut HashMap<String, (char, usize, usize, bool)>, _staged: bool) -> Result<()> {
    Ok(())
}

fn file_patch_stats(_repo: &Repository, diff: &git2::Diff, idx: usize) -> (usize, usize, bool) {
    // Use patch to count added/deleted and detect binary
    if let Ok(patch) = git2::Patch::from_diff(diff, idx) {
        if patch.is_binary().unwrap_or(false) {
            return (0,0,true);
        }
        let mut a = 0; let mut d = 0;
        if let Ok(n) = patch.num_hunks() {
            for h in 0..n {
                if let Ok((_, h_a, h_d)) = patch.line_stats(None, h) {
                    // line_stats returns (context, added, deleted)? Actually (context, additions, deletions)
                    a += h_a; d += h_d;
                }
            }
        }
        // Fallback: if no hunks (e.g., new file with no hunks?)? Use num_lines?
        return (a,d,false);
    }
    (0,0,false)
}

