                    } else {
                        labs.push(lname.clone());
                    }
                }
            }
            // remotes at this commit where local not same
            for (rname, roid) in &remote_map {
                if *roid == cd.id {
                    // check if local same-named exists and same commit (already aggregated)
                    if let Some(short) = rname.strip_prefix("origin/") {
                        if let Some(loid) = local_map.get(short) {
                            if *loid == cd.id {
                                continue; // aggregated, skip
                            }
                        }
                    }
                    labs.push(rname.clone());
                }
            }
            // sort: HEAD first, then alpha
            // Determine HEAD label: if head_branch Some(b), find lab that corresponds to b (either "b" or "b ↔ origin")
            let head_lab: Option<String> = if let Some(hb) = &head_branch {
                // find lab starting with hb
                labs.iter().find(|l| *l == hb || l.starts_with(&format!("{} ", hb)) || l.starts_with(&format!("{} ↔", hb))).cloned()
            } else { None };
            labs.sort();
            if let Some(hl) = head_lab {
                // move to front
                if let Some(pos) = labs.iter().position(|x| x == &hl) {
                    let v = labs.remove(pos);
                    labs.insert(0, v);
                }
            }
            labels[idx] = labs;
        }
        // uncommitted
        let uncommitted = if head_oid.is_some() {
            detect_uncommitted(repo)?
        } else { None };
        // graph lanes
        let (rows, max_lanes, commit_lanes) = build_graph(&commits, &labels, head_oid, uncommitted.is_some());
        Ok(Self {
            repo_path: repo.workdir().map(|p| p.to_path_buf()).unwrap_or_else(|| repo.path().to_path_buf()),
            repo_name,
            head_branch,
            head_oid,
            is_detached,
            branches,
            local_branches: local_map,
            remote_branches: remote_map,
            commits,
            commit_index,
            labels,
            uncommitted,
            rows,
            max_lanes,
            commit_lanes,
        })
    }
    fn label_for(&self, commit_idx: usize, branch_sel: usize) -> Option<String> {
        self.labels.get(commit_idx).and_then(|v| v.get(branch_sel).cloned())
    }
}

fn short_id(oid: Oid) -> String {
