    error_msg: Option<ErrorMsg>,
    success_msg: Option<(String, Instant)>, // msg + shown time
    fetching: bool, // yellow fetching in progress?
    fetching_start: Option<Instant>,
    // for fetch async
    fetch_rx: Option<std::sync::mpsc::Receiver<FetchResult>>,
    last_refresh: Instant,
    last_fetch: Instant,
    // cached diffs per commit idx? Compute on demand and cache
    diff_cache: HashMap<usize, (Vec<ChangedFile>, usize, usize, usize)>,
    // for connector rows, files panel shows last commit's files (stale) - need to track last commit's diff
    last_commit_diff: Option<(Vec<ChangedFile>, usize, usize, usize)>,
    last_commit_idx: Option<usize>,
    // for uncommitted diff, use state.uncommitted
    should_quit: bool,
    // for fetch error quirk: after Esc/q, show cyan fetching for 4.3s then normal
    fetch_dismiss_fetching_until: Option<Instant>,
}

struct ErrorMsg {
    text: String,
    show_hint: bool, // true for checkout/create (Esc/Enter close), false for fetch (no hint? Actually fetch shows no hint, just ERROR)
    is_fetch: bool,
}

struct FetchResult {
    success: bool,
    stderr: String,
}

impl App {
    fn new(repo: Repository, config: RefreshConfig) -> Result<Self> {
        let state = RepoState::load(&repo)?;
        let now = Instant::now();
        Ok(Self {
            repo,
            state,
            config,
            selected_row: 0,
            selected_branch: 0,
            scroll_offset: 0,
            help_visible: false,
            confirm_branch: None,
            confirm_commit_idx: None,
            new_branch_input: None,
            search: None,
            error_msg: None,
            success_msg: None,
            fetching: false,
            fetching_start: None,
            fetch_rx: None,
            last_refresh: now,
            last_fetch: now,
            diff_cache: HashMap::new(),
            last_commit_diff: None,
            last_commit_idx: None,
            should_quit: false,
            fetch_dismiss_fetching_until: None,
        })
    }

    fn refresh(&mut self) {
        // preserve selection by commit id / uncommitted?
        let sel_id: Option<Oid> = self.current_commit_oid();
        let sel_is_uncommitted = self.is_selected_uncommitted();
        let sel_branch_name: Option<String> = self.current_branch_label();
        // reload state
        if let Ok(new_state) = RepoState::load(&self.repo) {
            self.state = new_state;
            self.diff_cache.clear();
            // restore selection
            if sel_is_uncommitted {
                if self.state.uncommitted.is_some() {
                    self.selected_row = 0;
                } else {
                    self.selected_row = 0;
                }
                self.selected_branch = 0;
            } else if let Some(oid) = sel_id {
                // find row with this commit
                let mut found: Option<usize> = None;
                for (idx, row) in self.state.rows.iter().enumerate() {
                    if let RowKind::Commit { commit_idx } = &row.kind {
                        if self.state.commits.get(*commit_idx).map(|c| c.id) == Some(oid) {
                            found = Some(idx);
                            break;
                        }
                    }
                }
                if let Some(f) = found {
                    self.selected_row = f;
                    // restore branch by name if possible
                    if let RowKind::Commit { commit_idx } = &self.state.rows[f].kind {
                        let labs = &self.state.labels[*commit_idx];
                        if let Some(bname) = sel_branch_name {
                            if let Some(pos) = labs.iter().position(|l| l == &bname) {
                                self.selected_branch = pos;
                            } else {
                                self.selected_branch = 0;
                            }
                        } else {
                            self.selected_branch = 0;
                        }
                    } else {
                        self.selected_branch = 0;
                    }
                } else {
                    // commit gone, clamp
                    if self.selected_row >= self.state.rows.len() {
                        self.selected_row = self.state.rows.len().saturating_sub(1);
                    }
                    self.selected_branch = 0;
                }
            } else {
                // was connector? Try to keep index?
                if self.selected_row >= self.state.rows.len() {
                    self.selected_row = self.state.rows.len().saturating_sub(1);
                }
                // keep branch?
            }
            // clamp scroll? Will adjust in render
            self.ensure_visible(18); // placeholder, actual height known in render; use 18 default
        }
        // update last_commit_diff if selected is commit?
        self.update_last_diff();
    }

    fn current_commit_oid(&self) -> Option<Oid> {
        self.state.rows.get(self.selected_row).and_then(|r| match &r.kind {
            RowKind::Commit { commit_idx } => self.state.commits.get(*commit_idx).map(|c| c.id),
            _ => None,
        })
    }
    fn is_selected_uncommitted(&self) -> bool {
        matches!(self.state.rows.get(self.selected_row).map(|r| &r.kind), Some(RowKind::Uncommitted))
    }
    fn current_branch_label(&self) -> Option<String> {
        if let Some(row) = self.state.rows.get(self.selected_row) {
            if let RowKind::Commit { commit_idx } = &row.kind {
                return self.state.labels.get(*commit_idx).and_then(|v| v.get(self.selected_branch).cloned());
            }
        }
        None
    }
    fn current_commit_idx(&self) -> Option<usize> {
        self.state.rows.get(self.selected_row).and_then(|r| match &r.kind {
            RowKind::Commit { commit_idx } => Some(*commit_idx),
            _ => None,
        })
    }

    fn update_last_diff(&mut self) {
        if let Some(cidx) = self.current_commit_idx() {
            let diff = self.get_commit_diff(cidx);
            self.last_commit_diff = Some(diff);
            self.last_commit_idx = Some(cidx);
        } else if self.is_selected_uncommitted() {
            // uncommitted diff is separate, don't update last_commit_diff? For connector after uncommitted, what does files show? Uncommitted files? Or previous commit? Let's see: if selected uncommitted then j to next (merge), then k back? Actually connector after uncommitted? No connector at top. For uncommitted->connector? No. So ignore.
        } else {
            // connector: keep last_commit_diff stale (don't update)
        }
    }

    fn get_commit_diff(&mut self, cidx: usize) -> (Vec<ChangedFile>, usize, usize, usize) {
        if let Some(v) = self.diff_cache.get(&cidx) {
            return v.clone();
        }
        let cd = match self.state.commits.get(cidx) {
            Some(c) => c.clone(),
            None => return (Vec::new(),0,0,0),
        };
        let res = commit_diff_stats(&self.repo, &cd);
        self.diff_cache.insert(cidx, res.clone());
        res
    }

    fn ensure_visible(&mut self, visible_height: usize) {
        if self.state.rows.is_empty() { self.scroll_offset = 0; return; }
        if self.selected_row < self.scroll_offset {
            self.scroll_offset = self.selected_row;
        } else if self.selected_row >= self.scroll_offset + visible_height {
            self.scroll_offset = self.selected_row + 1 - visible_height;
        }
        // clamp
        if self.scroll_offset + visible_height > self.state.rows.len() {
            self.scroll_offset = self.state.rows.len().saturating_sub(visible_height);
