// ============ Fuzzy search ============
fn fuzzy_match(query: &str, target: &str) -> Option<i32> {
    // case-sensitive subsequence? Returns score (lower better? or higher?)
    // Original: "fea" matches feature2 (pos0) before beta-feature (pos5) -> earlier pos better.
    // "bt" matches beta-feature (b...t) -> subsequence.
    // "MY" (upper) doesn't match lowercase -> case-sensitive.
    // Implement simple: check if query chars appear in order in target (case-sensitive).
    // Score: sum of positions? Or first match pos + gaps? Let's implement scoring that prefers earlier + contiguous.
    if query.is_empty() { return Some(0); }
    let q: Vec<char> = query.chars().collect();
    let t: Vec<char> = target.chars().collect();
    let mut ti = 0;
    let mut score: i32 = 0;
    let mut last_match: Option<usize> = None;
    let mut first_pos: Option<usize> = None;
    for qc in q.iter() {
        let mut found = false;
        while ti < t.len() {
            if t[ti] == *qc {
                if first_pos.is_none() { first_pos = Some(ti); }
                if let Some(last) = last_match {
                    score += (ti - last - 1) as i32 * 2; // gap penalty
                }
                last_match = Some(ti);
                ti += 1;
                found = true;
                break;
            }
            ti += 1;
        }
        if !found { return None; }
    }
    // Prefer shorter targets? And earlier first pos?
    score += first_pos.unwrap_or(0) as i32 * 3;
    score += (t.len() - q.len()) as i32; // length penalty
    Some(score)
}

fn fuzzy_filter(query: &str, branches: &[String]) -> Vec<(String, i32)> {
    let mut res: Vec<(String, i32)> = Vec::new();
    for b in branches {
        if let Some(s) = fuzzy_match(query, b) {
            res.push((b.clone(), s));
        }
    }
    res.sort_by(|a,b| a.1.cmp(&b.1).then(a.0.cmp(&b.0)));
    res
