fn add_normal_hints(spans: &mut Vec<Span>) {
    let hints = vec![
        (" j/k ", "move "),
        (" Enter ", "checkout "),
        (" b ", "branch "),
        (" f ", "fetch "),
        (" ? ", "help "),
        (" q ", "quit"),
    ];
    for (key, desc) in hints {
        spans.push(Span::styled(key.to_string(), Style::default().fg(Color::Indexed(0)).bg(Color::Indexed(6)).add_modifier(Modifier::BOLD)));
        spans.push(Span::styled(desc.to_string(), Style::default().fg(Color::Indexed(15))));
    }
}

